import React, { useState } from 'react';
import { UserIcon, MapPinIcon, PhoneIcon, TruckIcon, ClockIcon, GiftIcon, CheckCircleIcon } from '@heroicons/react/24/outline';

const Orders = () => {
  // Static Data - No Backend Needed
  const [order, setOrder] = useState({
    orderID: "ORD-2026-991",
    status: "Pending",
    paymentType: "Cash on Delivery",
    totalAmount: 5250.00,
    items: [
      { name: "Keells Sugar 1kg", quantity: 2, unitPriceAtSale: 250, isPacked: false },
      { name: "Anchor Milk Powder 400g", quantity: 1, unitPriceAtSale: 1100, isPacked: false },
      { name: "Munchee Super Cream Cracker", quantity: 3, unitPriceAtSale: 180, isPacked: false }
    ],
    customer: {
      name: "Saman Kumara",
      phoneNumber: "071-2345678",
      address: { houseNumber: "No. 45/A", street: "Temple Road", landMark: "Near Clock Tower" }
    }
  });

  const statuses = ['Pending', 'Packing', 'Out for Delivery', 'Delivered'];
  const currentIdx = statuses.indexOf(order.status);

  const advanceStatus = () => {
    if (currentIdx < statuses.length - 1) {
      setOrder({ ...order, status: statuses[currentIdx + 1] });
    }
  };

  const togglePacked = (idx) => {
    const newItems = [...order.items];
    newItems[idx].isPacked = !newItems[idx].isPacked;
    setOrder({ ...order, items: newItems });
  };

  return (
    <div className="flex h-screen bg-gray-50 font-sans">
      {/* Sidebar */}
      <aside className="w-64 bg-blue-800 text-white p-6 shadow-xl">
        <h1 className="text-2xl font-black italic">ONAKO <span className="text-yellow-400">BIGMART</span></h1>
        <div className="mt-10 bg-blue-700 p-3 rounded-lg border-l-4 border-yellow-400 flex items-center space-x-3">
          <TruckIcon className="w-6 h-6" /> <span className="font-bold">Orders</span>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-10 overflow-auto">
        <div className="max-w-4xl mx-auto">
          <header className="flex justify-between items-center mb-10">
            <h2 className="text-3xl font-extrabold text-gray-800">Delivery Console</h2>
            <span className="bg-blue-100 text-blue-800 px-4 py-1 rounded-full text-sm font-bold uppercase">{order.status}</span>
          </header>

          <div className="bg-white rounded-2xl shadow-sm border p-8">
             <h3 className="text-xl font-bold mb-6 text-blue-900">{order.orderID} - {order.customer.name}</h3>
             
             {/* Simple Stepper */}
             <div className="flex justify-between mb-10 relative">
                <div className="absolute top-5 left-0 w-full h-1 bg-gray-200 -z-0"></div>
                {statuses.map((s, i) => (
                  <div key={s} className={`z-10 flex flex-col items-center ${i <= currentIdx ? 'text-blue-600' : 'text-gray-400'}`}>
                    <div className={`w-10 h-10 rounded-full flex items-center justify-center ${i <= currentIdx ? 'bg-blue-600 text-white' : 'bg-gray-200 text-gray-500'}`}>
                       {i === 0 && <ClockIcon className="w-5 h-5"/>}
                       {i === 1 && <GiftIcon className="w-5 h-5"/>}
                       {i === 2 && <TruckIcon className="w-5 h-5"/>}
                       {i === 3 && <CheckCircleIcon className="w-5 h-5"/>}
                    </div>
                    <span className="text-xs font-bold mt-2">{s}</span>
                  </div>
                ))}
             </div>

             <div className="grid grid-cols-2 gap-10">
                <div className="border rounded-xl p-5">
                   <h4 className="font-bold mb-4 border-b pb-2 text-gray-600">Packing List</h4>
                   {order.items.map((item, i) => (
                     <div key={i} className="flex items-center space-x-3 mb-3">
                        <input type="checkbox" checked={item.isPacked} onChange={() => togglePacked(i)} className="w-5 h-5 rounded" />
                        <span className={item.isPacked ? 'line-through text-gray-400' : 'font-medium'}>{item.name} (x{item.quantity})</span>
                     </div>
                   ))}
                </div>
                <div className="bg-gray-50 rounded-xl p-5 border-dashed border-2">
                   <h4 className="font-bold mb-2 flex items-center"><MapPinIcon className="w-5 h-5 mr-1" /> Destination</h4>
                   <p className="text-sm font-bold text-gray-700">{order.customer.address.houseNumber}, {order.customer.address.street}</p>
                   <p className="text-xs text-blue-600 font-bold uppercase mt-1">Landmark: {order.customer.address.landMark}</p>
                   <div className="mt-4 flex items-center text-sm text-gray-500"><PhoneIcon className="w-4 h-4 mr-1"/> {order.customer.phoneNumber}</div>
                </div>
             </div>

             {currentIdx < 3 && (
               <button onClick={advanceStatus} className="mt-10 w-full bg-blue-700 hover:bg-blue-800 text-white py-4 rounded-xl font-black text-lg transition-all shadow-lg">
                 ADVANCE TO {statuses[currentIdx+1].toUpperCase()}
               </button>
             )}
          </div>
        </div>
      </main>
    </div>
  );
};

export default Orders;
